import java.io.*;
import java.util.*;
import java.util.regex.*;

class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        int[] ans = new int[n];
        int[] cur = sums;
        for (int i = n; i >= 1; --i) {
            int k = 1 << i;
            int d = cur[k - 1] - cur[k - 2];
            HashMap<Integer, Integer> cnt = new HashMap<>();
            for (int j = 0; j < k; ++j) {
                cnt.put(cur[j], cnt.getOrDefault(cur[j], 0) + 1);
            }
            int[] s1 = new int[k / 2];
            int[] s2 = new int[k / 2];
            int p = 0;
            int sign = 1;
            for (int j = 0; j < k; ++j) {
                int s = cur[j];
                int c = cnt.getOrDefault(s, 0);
                if (c == 0) continue;
                cnt.put(s, c - 1);
                int t = s + d;
                cnt.put(t, cnt.getOrDefault(t, 0) - 1);
                s1[p] = s;
                s2[p] = t;
                p++;
                if (t == 0) sign = -1;
            }
            ans[i - 1] = sign * d;
            cur = (sign == 1 ? s1 : s2);
        }
        return ans;
    }
}

