using namespace std;

class Solution {
public:
    vector<int> recoverArray(int n, vector<int>& sums) {
        sort(sums.begin(), sums.end());
        vector<int> ans;
        ans.reserve(n);
        for (int i = n; i >= 1; --i) {
            int k = 1 << i;
            int d = sums[k - 1] - sums[k - 2];
            unordered_map<int, int> cnt;
            cnt.reserve((size_t)k * 2 + 10);
            cnt.max_load_factor(0.7f);
            for (int j = 0; j < k; ++j) ++cnt[sums[j]];
            vector<int> sums1, sums2;
            sums1.reserve(k / 2);
            sums2.reserve(k / 2);
            int sign = 1;
            for (int j = 0; j < k; ++j) {
                int s = sums[j];
                auto it = cnt.find(s);
                if (it == cnt.end() || it->second == 0) continue;
                --it->second;
                int t = s + d;
                --cnt[t];
                sums1.push_back(s);
                sums2.push_back(t);
                if (t == 0) sign = -1;
            }
            ans.push_back(sign * d);
            sums = (sign == 1 ? sums1 : sums2);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
};

static vector<long long> parseInts(const string& s) {
    vector<long long> nums;
    for (size_t i = 0; i < s.size();) {
        while (i < s.size() && !(s[i] == '-' || isdigit((unsigned char)s[i]))) ++i;
        if (i >= s.size()) break;
        int sign = 1;
        if (s[i] == '-') { sign = -1; ++i; }
        long long v = 0;
        while (i < s.size() && isdigit((unsigned char)s[i])) {
            v = v * 10 + (s[i] - '0');
            ++i;
        }
        nums.push_back(sign * v);
    }
    return nums;
}

