#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int key;
    int count;
    unsigned char used;
} Entry;

static unsigned int hash_int(int x) {
    unsigned int z = (unsigned int)x;
    z ^= z >> 16;
    z *= 0x7feb352dU;
    z ^= z >> 15;
    z *= 0x846ca68bU;
    z ^= z >> 16;
    return z;
}

static void table_clear(Entry *tab, int cap) {
    memset(tab, 0, (size_t)cap * sizeof(Entry));
}

static Entry* table_get(Entry *tab, int cap, int key) {
    unsigned int h = hash_int(key) & (unsigned int)(cap - 1);
    while (tab[h].used && tab[h].key != key) {
        h = (h + 1U) & (unsigned int)(cap - 1);
    }
    if (!tab[h].used) {
        tab[h].used = 1;
        tab[h].key = key;
        tab[h].count = 0;
    }
    return &tab[h];
}

static int* parse_all_ints(const char *s, int *outCount) {
    int cap = 1024, n = 0;
    int *a = (int*)malloc((size_t)cap * sizeof(int));
    const char *p = s;
    while (*p) {
        while (*p && *p != '-' && !isdigit((unsigned char)*p)) ++p;
        if (!*p) break;
        int sign = 1;
        if (*p == '-') { sign = -1; ++p; }
        long long v = 0;
        while (*p && isdigit((unsigned char)*p)) {
            v = v * 10 + (*p - '0');
            ++p;
        }
        if (n == cap) {
            cap *= 2;
            a = (int*)realloc(a, (size_t)cap * sizeof(int));
        }
        a[n++] = (int)(sign * v);
    }
    *outCount = n;
    return a;
}

static int cmp_int(const void *a, const void *b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

int* recoverArray(int n, int* sums, int sumsSize, int* returnSize) {
    (void)sumsSize;
    qsort(sums, (size_t)(1 << n), sizeof(int), cmp_int);

    int *ans = (int*)malloc((size_t)n * sizeof(int));
    int *work = (int*)malloc((size_t)(1 << n) * sizeof(int));
    int *s1 = (int*)malloc((size_t)(1 << n) * sizeof(int));
    int *s2 = (int*)malloc((size_t)(1 << n) * sizeof(int));
    int *orig = sums;
    int totalCap = 1 << 18;
    Entry *tab = (Entry*)calloc((size_t)totalCap, sizeof(Entry));
    if (!ans || !work || !s1 || !s2 || !tab) {
        free(ans); free(work); free(s1); free(s2); free(tab);
        *returnSize = 0;
        return NULL;
    }

    int current = 1 << n;
    for (int i = n; i >= 1; --i) {
        int k = current;
        int d = orig[k - 1] - orig[k - 2];
        table_clear(tab, totalCap);
        for (int j = 0; j < k; ++j) {
            table_get(tab, totalCap, orig[j])->count++;
        }

        int p = 0;
        int sign = 1;
        for (int j = 0; j < k; ++j) {
            int s = orig[j];
            Entry *es = table_get(tab, totalCap, s);
            if (es->count == 0) continue;
            es->count--;
            Entry *et = table_get(tab, totalCap, s + d);
            et->count--;
            s1[p] = s;
            s2[p] = s + d;
            if (s + d == 0) sign = -1;
            p++;
        }

        ans[i - 1] = sign * d;
        int half = k / 2;
        if (sign == 1) {
            memcpy(orig, s1, (size_t)half * sizeof(int));
        } else {
            memcpy(orig, s2, (size_t)half * sizeof(int));
        }
        current = half;
    }

    *returnSize = n;
    free(work);
    free(s1);
    free(s2);
    free(tab);
    return ans;
}

